const button=document.createElement('button'),panel=document.createElement('div');button.id='emote-toggle';button.setAttribute('aria-label','감정 표현');button.setAttribute('aria-expanded','false');button.textContent='☺';panel.id='emote-panel';panel.hidden=true;panel.setAttribute('aria-label','감정 선택');for(const [kind,label,icon]of [['heart','하트','♡'],['joy','기쁨','✧'],['sad','슬픔','☂'],['surprise','놀람','!'],['dance','춤','♫']]){const b=document.createElement('button');b.textContent=icon;b.setAttribute('aria-label',label);b.onclick=()=>{window.dispatchEvent(new CustomEvent('lab:emote',{detail:kind}));panel.hidden=true;button.setAttribute('aria-expanded','false');};panel.append(b);}button.onclick=()=>{panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));};document.body.append(button,panel);window.addEventListener('keydown',e=>{if(e.key==='Escape'){panel.hidden=true;button.setAttribute('aria-expanded','false');}});
